                 upper_bound: Callable[[set[int]], int]) -> set[int]:
    active = set(graph)
    while True:
        victim = next((v for v in sorted(active)
                       if 1 + upper_bound(active & graph[v]) < target), None)
        if victim is None:
            return active
        active.remove(victim)

from __future__ import annotations
from typing import Callable

def cascade_bound(region: set[int], pattern_size: int, target: int,
                  bounds: list[Callable[[set[int]], int]]) -> tuple[int, bool]:
    best = len(region)
    for bound in bounds:
        best = min(best, bound(region))
        if pattern_size + best < target:
            return best, True
    return best, pattern_size + best < target

